sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.helpers
 */
function handler({api, event, helpers}) {

	var participantId =
		event.payload.data.output.data.GlideRecord_Mutation
			.insert_x_1892173_stopwa_0_participant.sys_id.value;

	var code = api.context.props.code;

	api.setState("createdParticipantId", participantId);

	// Keep the event for our application flow
	api.emit("PARTICIPANT_CREATED", {
		participantId: participantId,
		code: code
	});

	// Navigate directly to Participant Buzzer
	helpers.navigate.to(
		"participant-buzzer",
		{
			code: code
		},
		{
			participantId: participantId
		}
	);
}
